import { defineExperiment } from "niceeval";
import { codexAgent } from "niceeval/adapter";
import { codexSandbox } from "../shared/sandbox.ts";

export default defineExperiment({
  description: "Codex model comparison on isolated Express maintenance tasks",
  agent: codexAgent(),
  model: "gpt-5.4-mini",
  runs: 1,
  maxConcurrency: 1,
  timeoutMs: 600_000,
  sandbox: codexSandbox,
});

